import "server-only";

import { NextResponse } from "next/server";

import { getPosts } from "@/lib/api/server";
import type { Locale } from "@/lib/i18n/config";

/**
 * The feed itself is generated by the Go API (it owns the data); the routes
 * that call this just proxy it so the public URL lives on the site's own
 * domain. One feed per locale: /en/feed.xml, /da/feed.xml, plus /feed.xml as
 * the English one so subscriptions made before translations keep working.
 */
const INTERNAL =
  process.env.API_INTERNAL_URL ??
  process.env.NEXT_PUBLIC_API_URL ??
  "http://localhost:8080";

export async function feedResponse(locale: Locale): Promise<NextResponse> {
  // No posts means no feed at all, matching the hidden nav link and the 404 on
  // /blog. The count is cached under the same "posts" tag as the feed, so this
  // check is free.
  const count = await getPosts({ locale, limit: 1 })
    .then((r) => r.total)
    .catch(() => 0);
  if (count === 0) {
    return new NextResponse("no posts yet", { status: 404 });
  }

  // A build runs without the API reachable, so a failure here must not fail
  // the build - the route is revalidated and recovers on its own.
  let res: Response;
  try {
    res = await fetch(`${INTERNAL}/api/v1/feed.xml?lang=${locale}`, {
      next: { revalidate: 900, tags: ["posts"] },
    });
  } catch {
    return new NextResponse("feed unavailable", { status: 503 });
  }
  if (!res.ok) {
    return new NextResponse("feed unavailable", { status: 502 });
  }
  return new NextResponse(await res.text(), {
    headers: {
      "Content-Type": "application/rss+xml; charset=utf-8",
      "Cache-Control": "public, max-age=900",
    },
  });
}
